"""Self-contained local HTML; no server, framework, fetch, or remote asset."""
from demo_runtime import *

HTML=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rule Model v0.1 · 실제 로그 개발 데모</title>
<style>
:root{--bg:#f3f5f8;--ink:#19273a;--muted:#637286;--line:#dbe2eb;--blue:#285fc4;--green:#14734d;--red:#b43239;--amber:#956507}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Noto Sans KR",sans-serif}header{background:#172d50;color:white;padding:28px max(24px,calc((100vw - 1360px)/2))}header h1{margin:0;font-size:26px}header p{margin:8px 0 0;color:#d6e3f8}main{max-width:1408px;margin:auto;padding:22px 24px}.notice{background:#eef3fd;border:1px solid #bed0f0;border-radius:10px;padding:12px 16px;margin-bottom:20px}.stats{display:grid;grid-template-columns:repeat(7,1fr);gap:10px}.stat{padding:15px;background:white;border:1px solid var(--line);border-radius:10px}.stat b{display:block;font-size:25px}.stat span{color:var(--muted);font-size:12px}section{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;margin:20px 0}h2{font-size:18px;margin:0 0 14px}h3{font-size:15px;margin:18px 0 10px}.muted{color:var(--muted)}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}input,select,button{font:inherit;border:1px solid var(--line);border-radius:6px;padding:8px;background:white}input{min-width:230px}button{cursor:pointer;color:var(--blue)}.scroll{overflow:auto;max-height:440px;border:1px solid var(--line);border-radius:8px}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th,td{padding:9px 11px;border-bottom:1px solid var(--line);vertical-align:top}th{position:sticky;top:0;background:#f6f8fb;z-index:1}tbody tr{cursor:pointer}tbody tr:hover{background:#edf3ff}tr.selected{background:#e9f0fc}.pill{display:inline-block;border-radius:20px;padding:3px 9px;font-size:11px;white-space:nowrap;background:#eef1f5;color:var(--muted)}.validated{background:#e4f4ec;color:var(--green)}.failed{background:#fbe8e9;color:var(--red)}.deferred,.awaiting_meaning_review{background:#fff4d8;color:var(--amber)}.request_evidence{background:#e6efff;color:var(--blue)}.manual{background:#f1eafa;color:#71489d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{min-width:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fb;border:1px solid var(--line);border-radius:7px;padding:13px;font:12px/1.6 ui-monospace,monospace;max-height:470px;overflow:auto}#decisionHeadline{font-size:17px;font-weight:650}.detailfacts{display:flex;gap:8px;flex-wrap:wrap}.reason{white-space:pre-wrap;border-left:3px solid #a6bfdc;padding:8px 13px;background:#f6f9fd}details{margin-top:10px}summary{cursor:pointer;color:var(--blue)}.manual-block{border:2px solid #cbb6e5;background:#fbf8fe;padding:16px;border-radius:9px;margin-top:12px}footer{color:var(--muted);padding:0 0 30px;font-size:12px}.empty{padding:20px;color:var(--muted)}a{color:var(--blue)}@media(max-width:900px){.stats{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}main{padding:16px}section{padding:15px}}@media(max-width:480px){.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><header><h1>Rule Model v0.1</h1><p>Qwen3.6-27B + 고정 SFT v2 · 실제 로그 입력 → 규칙 제안 → 코드 검증 → 직접 의미 확인</p></header><main>
<div class="notice">기존 실제 평가 32건을 재사용한 <b>개발 데모</b>입니다. 입력의 피처·측정·근거를 보존하며 모델 답안을 코드로 정답으로 바꾸지 않습니다. 수동 예제는 별도 표시하고 모델 성공 수에서 제외합니다. 현재 표본의 빈도·기준선은 오프라인 포착 범위에 한정됩니다.</div>
<div class="stats" id="stats"></div>
<section><h2>① 피처 64개와 실제 측정</h2><div class="toolbar"><input id="featureSearch" aria-label="피처 검색" placeholder="피처 ID·의미·방법 검색"><span class="muted" id="featureCount"></span></div><div class="scroll"><table><thead><tr><th>ID / 출처</th><th>의미</th><th>계산 방법 / 분석 단위</th><th>타입 / 단위</th><th>유효 / 전체</th><th>결측 / 변동</th></tr></thead><tbody id="features"></tbody></table></div><details><summary>선택 피처의 정의·정책·원천 SHA</summary><pre id="featureJSON"></pre></details></section>
<section><h2>② 모델 결과 32건</h2><div class="toolbar"><select id="statusFilter" aria-label="상태 필터"><option value="all">모든 상태</option><option value="validated">검증 통과</option><option value="deferred">보류</option><option value="request_evidence">추가 근거 요청</option><option value="no_applicable">적용 불가</option><option value="failed">실패</option><option value="awaiting_meaning_review">의미 검토 대기</option></select><span class="muted" id="responseCount"></span></div><div class="scroll"><table><thead><tr><th>입력 / 피처</th><th>상태</th><th>HR/SR / 모델 상태</th><th>실제 조건 AST</th><th>최초 → 수정</th></tr></thead><tbody id="decisions"></tbody></table></div></section>
<section><h2>③ 대표 결과의 근거·입력·출력</h2><div class="toolbar"><select id="caseSelect" aria-label="대표 입력 선택"></select><button id="copyInput">입력 JSON 복사</button><span class="muted" id="copyState"></span></div><div id="decisionHeadline"></div><p class="muted" id="readable"></p><div class="detailfacts" id="facts"></div><h3>모델이 작성한 이유 원문</h3><div class="reason" id="reason"></div><div class="grid"><div class="panel"><h3>사용한 측정값·확인된 제약·기준선</h3><pre id="evidenceJSON"></pre></div><div class="panel"><h3>코드 검증과 직접 검토</h3><pre id="validationJSON"></pre></div></div><div class="grid"><div class="panel"><h3>실제 입력 JSON</h3><pre id="inputJSON"></pre></div><div class="panel"><h3>최종 모델 출력 원문</h3><pre id="outputJSON"></pre><details><summary>최초·수정 응답을 모두 확인</summary><div id="history"></div></details></div></div></section>
<section><h2>④ reviewed_manual 예제 · 모델 출력과 별도</h2><p class="muted">아래 예제는 모델 생성 성공에 포함하지 않습니다. 검토된 수동 명세가 필요한 경우에만 표시합니다.</p><div id="manualExamples"></div></section>
<section><h2>⑤ 실행과 파일</h2><pre id="command"></pre><div class="toolbar"><a href="README.md">README</a><a href="../../models/rule_generator_v0_1/model_manifest.json">모델 경로·버전</a><a href="feature_catalog.json">피처64</a><a href="example_inputs.jsonl">입력32</a><a href="model_outputs.jsonl">최초·수정 원문</a><a href="validated_rules.json">승인 규칙</a><a href="pending_decisions.json">보류·근거 요청·적용 불가</a><a href="failed_outputs.jsonl">실패</a></div><pre id="limits"></pre></section>
<footer>정적 HTML · 외부 서버·패키지·네트워크 없이 열 수 있습니다. 이 화면은 이상탐지를 실행하지 않습니다. 모델·어댑터·측정·기존 실패 결과는 보존됩니다.</footer></main>
<script id="demoData" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('demoData').textContent);const labels={validated:'검증 통과',deferred:'보류',request_evidence:'추가 근거 요청',no_applicable:'적용 불가',failed:'실패',awaiting_meaning_review:'의미 검토 대기',unexecuted:'미실행'};const $=id=>document.getElementById(id);const fmt=x=>JSON.stringify(x,null,2);let selectedID=null;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}function pill(s){return node('span',labels[s]||s,'pill '+s)}
function showFeature(fid){const f=D.features.find(x=>x.id===fid);if(f)$('featureJSON').textContent=fmt(f);document.querySelectorAll('#features tr').forEach(r=>r.classList.toggle('selected',r.dataset.id===fid))}
function renderFeatures(){const q=$('featureSearch').value.toLowerCase();const fs=D.features.filter(f=>[f.id,f.meaning,f.method,f.origin].join(' ').toLowerCase().includes(q));$('features').replaceChildren();fs.forEach(f=>{const s=f.measurement.summary,r=node('tr');r.dataset.id=f.id;r.append(node('td',f.id+' · '+(f.origin==='model_discovered_reused'?'기존 모델':'기존 코드')),node('td',f.meaning),node('td',f.method+' / '+f.plan.grain.table),node('td',f.dtype+' / '+(f.unit??'미확인')),node('td',s.valid_count+' / '+s.row_count),node('td',s.missing_count+' / '+s.variation));r.onclick=()=>{showFeature(f.id);const x=D.results.find(x=>x.input.feature.id===f.id);if(x){$('caseSelect').value=x.id;showCase(x.id)}};$('features').append(r)});$('featureCount').textContent=fs.length+' / 64개 · 모델 출처13 / 코드 출처51 · 이번 새 피처0'}
function renderDecisions(){const f=$('statusFilter').value;const rs=D.results.filter(x=>f==='all'||x.status===f);$('decisions').replaceChildren();rs.forEach(x=>{const r=node('tr'),p=x.decision||{},history=D.outputs.filter(v=>v.id===x.id);r.dataset.id=x.id;r.append(node('td',x.id+' / '+x.input.feature.id));const st=node('td');st.append(pill(x.status));r.append(st,node('td',(p.role||'?')+' / '+(p.state||'?')),node('td',JSON.stringify(p.condition??null)),node('td','최초'+(history.some(h=>h.stage==='repair')?' → 수정1회':'')));r.onclick=()=>{$('caseSelect').value=x.id;showCase(x.id)};$('decisions').append(r)});$('responseCount').textContent=rs.length+' / '+D.results.length+'건 · 최초'+D.summary.initial_responses+' / 수정'+D.summary.repair_responses+' · 직접 검토 후 승인'}
function showCase(id){selectedID=id;const x=D.results.find(x=>x.id===id);if(!x)return;const i=x.input,p=x.decision||{};$('decisionHeadline').replaceChildren(pill(x.status),node('span',' '+id+' · '+(p.role||'?')+' · '+JSON.stringify(p.condition??null)));$('readable').textContent=x.readable_summary;$('reason').textContent=x.model_reason_original||'파싱 가능한 모델 이유가 없습니다. 원문을 확인하세요.';$('inputJSON').textContent=fmt(i);$('outputJSON').textContent=x.raw_output;$('evidenceJSON').textContent=fmt({feature:i.feature,scope:i.scope,measurement_id:i.measurement_id,measurement:i.measurement,constraints:i.constraints,baseline:i.baseline,version:i.version});$('validationJSON').textContent=fmt({code_validation:x.code_validation,human_review:x.human_review,output_semantically_rewritten:false});$('facts').replaceChildren(...['유효 '+i.measurement.valid_count,'계산 불가 '+i.measurement.missing_count,'Boolean 참 '+(i.measurement.true_count===null?'해당 없음':String(i.measurement.true_count)),'단위 '+String(i.feature.unit),'근거 '+(p.evidence||[]).join(',')].map(s=>node('span',s,'pill')));$('history').replaceChildren();D.outputs.filter(v=>v.id===id).forEach(v=>{const d=node('div');d.append(node('h3',v.stage==='initial'?'최초 생성':'수정 생성 · 최대1회'),node('pre',v.raw_output),node('pre',fmt(v.validation)));$('history').append(d)});showFeature(i.feature.id);document.querySelectorAll('#decisions tr').forEach(r=>r.classList.toggle('selected',r.dataset.id===id))}
[['피처',64],['모델 HR 승인',D.summary.validated_model_HR],['모델 SR 승인',D.summary.validated_model_SR],['보류',D.summary.deferred],['근거 요청',D.summary.request_evidence],['적용 불가',D.summary.no_applicable],['실패',D.summary.failed]].forEach(([s,n])=>{const d=node('div',undefined,'stat');d.append(node('b',String(n)),node('span',s));$('stats').append(d)});
D.results.forEach(x=>{const o=node('option',x.id+' · '+(labels[x.status]||x.status));o.value=x.id;$('caseSelect').append(o)});$('featureSearch').oninput=renderFeatures;$('statusFilter').onchange=renderDecisions;$('caseSelect').onchange=e=>showCase(e.target.value);$('copyInput').onclick=async()=>{try{await navigator.clipboard.writeText($('inputJSON').textContent);$('copyState').textContent='복사했습니다'}catch(e){$('copyState').textContent='브라우저의 파일 권한 제한으로 직접 텍스트를 선택해 복사하세요'}};
if(!D.manual.length)$('manualExamples').append(node('p','수동 예제 없음 · 모델 결과만 표시합니다.'));D.manual.forEach(m=>{const box=node('div',undefined,'manual-block');box.append(node('span','reviewed_manual · 모델 성공 수 제외','pill manual'),node('h3',m.id+' · '+m.decision.role),node('pre',fmt(m.decision)),node('p',m.review_note||''));$('manualExamples').append(box)});$('command').textContent=D.command;$('limits').textContent=D.summary.limits.join('\n')+'\n코드 통과·직접 검토 승인·모델 생성 출처를 구분합니다.\n미실행 또는 의미 검토 대기는 성공으로 세지 않습니다.';renderFeatures();renderDecisions();if(D.results.length){const x=D.results.find(x=>x.status==='validated')||D.results[0];$('caseSelect').value=x.id;showCase(x.id)}else{showFeature('f001');$('reason').textContent='모델 실행 결과를 준비 중입니다.'}
</script></body></html>'''

def render(out):
 out=Path(out)
 if out!=EVAL:
  for name in ['README.md','model_manifest.json','feature_catalog.json','example_inputs.jsonl','output_contract.json']:
   source=(PKG/name)if name in {'model_manifest.json','output_contract.json'}else(EVAL/name)
   if not(out/name).exists()and source.exists():(out/name).write_bytes(source.read_bytes())
 summary=read(out/'summary.json');data={'features':read(EVAL/'feature_catalog.json'),'summary':summary,'results':read(out/'demo_results.json'),'outputs':rows(out/'model_outputs.jsonl')if(out/'model_outputs.jsonl').exists()else [],'manual':read(out/'reviewed_manual_examples.json')if(out/'reviewed_manual_examples.json').exists()else [],'command':"# 저장소 루트에서 실행\npython -B research/models/rule_generator_v0_1/demo_cli.py inspect\n\n# 할당된 GPU와 로컬 Qwen 경로를 지정한 뒤 실행\npython -B research/models/rule_generator_v0_1/demo_cli.py run --input-json research/evaluation/rule_generator_v0_1/examples/real_01_f004.json --max-repairs 1"}
 encoded=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
 relative_manifest=os.path.relpath(PKG/'model_manifest.json',out)
 page=HTML.replace('../../models/rule_generator_v0_1/model_manifest.json',relative_manifest)
 (out/'demo.html').write_text(page.replace('__DATA__',encoded),encoding='utf-8')
 print('HTML_READY',out/'demo.html',flush=True)
